 const legacyTitle=document.createElement('div');legacyTitle.className='v7-nav-title';legacyTitle.textContent='Quick management tools';const oldTab=nav.querySelector('[data-tab]');if(oldTab)nav.insertBefore(legacyTitle,oldTab);
 const global=document.createElement('div');global.className='v7-global-search';global.innerHTML='<label><span class="sr-only">Global search</span><input id="v7GlobalSearch" placeholder="Search students, receipts, phone, UTR…" aria-label="Global search"></label>';$('.topbar').append(global);
 const btn=(label,action,id='',extra='')=>'<button class="btn" data-v7-action="'+action+'" data-id="'+esc(id)+'" '+extra+'>'+esc(label)+'</button>';
