 function header(title,actions=''){return '<div class="v7-heading"><div><p class="v7-eyebrow">Aacharya Learning Academy</p><h2>'+esc(title)+'</h2><p class="muted">'+esc(today())+' · Academy workspace</p></div><div class="actions">'+actions+'</div></div>';}
 async function lookups(force=false){if(state.lookups.students&&!force)return state.lookups;const [s,t,su,b,e]=await Promise.all([request('/api/students'),request('/api/teachers'),request('/api/subjects'),request('/api/batches'),request('/api/enrollments')]);return state.lookups={students:s.students,teachers:t.teachers,subjects:su.subjects,batches:b.batches,enrollments:e.enrollments};}
 const options=(type,label)=>[['','Select '+label],...(state.lookups[type]||[]).map(x=>[x.id,(x.student_code?x.student_code+' · ':'')+(x.full_name||x.name||x.course_name)+(x.student?' · '+x.student:'')])];
 const select=(name,label,type,required=false)=>[name,label,'select',options(type,label),required?'required':''];
 const choice=(name,label,items,required=false)=>[name,label,'select',items,required?'required':''];
